        #region 状态机
        private class KrakenStateMachine : EntityStateMachine
        {
            public KrakenStateMachine()
            {
                // Phase 1
                AddState(new HiddenState());

                // Phase 2
                AddState(new AppearState());
                AddState(new IdleState());
                AddState(new EyesState());
                AddState(new RoarState());
                AddState(new LaserEyeState());
                AddState(new AbsorbState());
                AddState(new DrainageState());

                // Phase 3
                AddState(new SwitchPhase2State());
                AddState(new CommandRoarState());
                //AddState(new TimeBombState());

                // Extra
                AddState(new StunnedState());
                AddState(new DeathState());
            }
        }
        #endregion

        private static void CheckDeath(Entity entity)
        {
            if (!entity.IsDead)
                return;
            stateMachine.StartState(entity, STATE_DEATH);
        }

        private static void SetExposedStates(Entity entity, bool exposed)
        {
            SetInvincible(entity, !exposed);
            SetInactive(entity, !exposed);
            SetShadowAlpha(entity, exposed ? 1 : 0);
        }

        #region 隐藏
        private class HiddenState : EntityStateMachineState
        {
            public HiddenState() : base(STATE_HIDDEN, ANIMATION_STATE_HIDDEN) { }
            public override void OnEnter(EntityStateMachine stateMachine, Entity entity)
            {
                base.OnEnter(stateMachine, entity);
                SetExposedStates(entity, false);
            }
            public override void OnExit(EntityStateMachine machine, Entity entity)
            {
                base.OnExit(machine, entity);
                SetInactive(entity, false);
                entity.Level.RemoveLoopSoundEntity(VanillaSoundID.earthquake, entity.ID);
            }
            public override void OnUpdateAI(EntityStateMachine machine, Entity entity)
            {
                base.OnUpdateAI(machine, entity);
                var substate = stateMachine.GetSubState(entity);
                var timer = stateMachine.GetSubStateTimer(entity);
                timer.Run(stateMachine.GetSpeed(entity));
                switch (substate)
                {
                    case SUBSTATE_HIDDEN:
                        // 转阶段
                        if (AllTentaclesAreDead(entity))
                        {
                            stateMachine.StartSubState(entity, SUBSTATE_WAITING);
                            timer.ResetSeconds(3f);
                        }
                        break;
                    case SUBSTATE_WAITING:
                        if (timer.Expired)
                        {
                            stateMachine.StartSubState(entity, SUBSTATE_SHAKING);
                            timer.ResetSeconds(3f);
                            entity.Level.AddLoopSoundEntity(VanillaSoundID.earthquake, entity.ID);
                        }
                        break;
                    case SUBSTATE_SHAKING:
                        entity.Level.ShakeScreen(15, 15, 1);
                        if (timer.Expired)
                        {
                            SwitchToPhase2(entity);
                        }
                        break;
                }
            }
            public override void OnUpdateLogic(EntityStateMachine machine, Entity entity)
            {
                base.OnUpdateLogic(machine, entity);
                CheckDeath(entity);
            }
            public const int SUBSTATE_HIDDEN = 0;
            public const int SUBSTATE_WAITING = 1;
            public const int SUBSTATE_SHAKING = 2;
        }
        #endregion

        #region 出现
        private class AppearState : EntityStateMachineState
        {
            public AppearState() : base(STATE_APPEAR, ANIMATION_STATE_APPEAR) { }
            public override void OnEnter(EntityStateMachine stateMachine, Entity entity)
            {
                base.OnEnter(stateMachine, entity);
                var substateTimer = stateMachine.GetSubStateTimer(entity);
                substateTimer.ResetSeconds(0.5f);
                SetInvincible(entity, true);
                SetInactive(entity, false);

                AdjustZ(entity);
            }
            public override void OnUpdateAI(EntityStateMachine stateMachine, Entity entity)
            {
                base.OnUpdateAI(stateMachine, entity);
                var substate = stateMachine.GetSubState(entity);
                var timer = stateMachine.GetSubStateTimer(entity);
                timer.Run(stateMachine.GetSpeed(entity));
                switch (substate)
                {
                    case SUBSTATE_FLOATING:
                        SetShadowAlpha(entity, timer.GetPassedPercentage());
                        if (timer.Expired)
                        {
                            stateMachine.StartSubState(entity, SUBSTATE_OUT);
                            timer.ResetSeconds(1f);
                            PlaySplash(entity);
                            entity.Level.ShakeScreen(10, 0, 15);
                        }
                        break;
                    case SUBSTATE_OUT:
                        if (timer.Expired)
                        {
                            stateMachine.StartState(entity, STATE_ROAR);
                            ResummonTentacles(entity, 2, false);
                        }
                        break;
                }
            }
            public override void OnUpdateLogic(EntityStateMachine machine, Entity entity)
            {
                base.OnUpdateLogic(machine, entity);
                CheckDeath(entity);
            }
            public const int SUBSTATE_FLOATING = 0;
            public const int SUBSTATE_OUT = 1;
        }
        #endregion

        #region 待命
        private static bool CanSwitchStatePhase2(Entity entity, int state)
        {
            switch (state)
            {
                case STATE_EYES:
                    return HasEyeTarget(entity);
                case STATE_ROAR:
                    return HasRoarTarget(entity);
                case STATE_LASER_EYE:
                    return HasLaserEyeTarget(entity);
                case STATE_ABSORB:
                    return HasAbsorbTarget(entity);
                case STATE_DRAINAGE:
                    return HasDrainageTarget(entity);
            }
            return true;
        }
        private static bool CanSwitchStatePhase3(Entity entity, int state)
        {
            switch (state)
            {
                case STATE_EYES:
                    return HasEyeTarget(entity);
                case STATE_COMMAND_ROAR:
                    return HasCommandRoarTarget(entity);
                    //case STATE_TIME_BOMB:
                    //    return HasTimeBombTarget(entity);
            }
            return true;
        }
        private static void SwitchState(Entity entity, int state)
        {
            switch (state)
            {
                case STATE_LASER_EYE:
                    {
                        var lane = FindLaserEyeLane(entity);
                        SetTargetLane(entity, lane);
                        stateMachine.StartState(entity, state);
                    }
                    break;
                default:
                    {
                        stateMachine.StartState(entity, state);
                    }
                    break;
            }
        }
        private class IdleState : EntityStateMachineState
        {
            public IdleState() : base(STATE_IDLE, ANIMATION_STATE_IDLE) { }
            public override void OnEnter(EntityStateMachine stateMachine, Entity entity)
            {
                base.OnEnter(stateMachine, entity);

                var stateTimer = stateMachine.GetStateTimer(entity);
                stateTimer.ResetSeconds(2f);
                SetExposedStates(entity, true);
            }
            public override void OnUpdateAI(EntityStateMachine stateMachine, Entity entity)
            {
                base.OnUpdateAI(stateMachine, entity);

                // 转阶段
                if (entity.Health <= entity.GetMaxHealth() * PHASE_3_THRESOLD_HP_PERCENTAGE && entity.GetPhase() == PHASE_2)
                {
                    SwitchToPhase3(entity);
                    return;
                }

                var stateTimer = stateMachine.GetStateTimer(entity);
                if (AreAllTentaclesHiddenOrDead(entity))
                {
                    stateTimer.Run(stateMachine.GetSpeed(entity));
                }
                if (stateTimer.Expired)
                {
                    var nextIndex = stateMachine.GetNextStateIndex(entity);
                    int[] pool;
                    var phase = entity.GetPhase();
                    switch (phase)
                    {
                        case PHASE_1:
                        case PHASE_2:
                        default:
                            pool = statePoolPhase2;
                            nextIndex = pool.FindNextStateIndex(nextIndex, state => CanSwitchStatePhase2(entity, state));
                            break;
                        case PHASE_3:
                            pool = statePoolPhase3;
                            nextIndex = pool.FindNextStateIndex(nextIndex, state => CanSwitchStatePhase3(entity, state));
                            break;
                    }
                    if (nextIndex >= 0)
                    {
                        var state = pool[nextIndex];
                        stateMachine.SetNextStateIndex(entity, nextIndex + 1);
                        SwitchState(entity, state);
                    }
                    else
                    {
                        stateTimer.Reset();
                    }
                }
            }
            public override void OnUpdateLogic(EntityStateMachine machine, Entity entity)
            {
                base.OnUpdateLogic(machine, entity);
                CheckDeath(entity);
            }
        }
        #endregion

        #region 眼睛
        public static Entity? FindEyeTarget(Entity boss)
        {
            return FindBarrageEyeTarget(boss) ?? FindFlameEyeTarget(boss);
        }
        public static Entity? FindBarrageEyeTarget(Entity boss)
        {
            var eyePosition = GetBlueEyePosition(boss);
            return barrageEyeDetector.DetectEntityWithTheLeast(boss, e => (e.GetCenter() - eyePosition).sqrMagnitude);
        }
        public static Entity? FindFlameEyeTarget(Entity boss)
        {
            var eyePosition = GetGreenEyePosition(boss);
            return flameEyeDetector.DetectEntityWithTheLeast(boss, e => (e.GetCenter() - eyePosition).sqrMagnitude);
        }
        public static bool HasEyeTarget(Entity boss)
        {
            return HasBarrageEyeTarget(boss) || HasFlameEyeTarget(boss);
        }
        public static bool HasBarrageEyeTarget(Entity boss)
        {
            return barrageEyeDetector.DetectExists(boss);
        }
        public static bool HasFlameEyeTarget(Entity boss)
        {
            return flameEyeDetector.DetectExists(boss);
        }
        private class EyesState : EntityStateMachineState
        {
            public EyesState() : base(STATE_EYES, ANIMATION_STATE_EYES) { }
            public override int GetAnimationSubstate(int substate)
            {
                switch (substate)
                {
                    case SUBSTATE_END:
                        return ANIMATION_SUBSTATE_END;
                }
                return ANIMATION_SUBSTATE_START;
            }
            public override void OnEnter(EntityStateMachine stateMachine, Entity entity)
            {
                base.OnEnter(stateMachine, entity);
                SetExposedStates(entity, true);

                var timer = stateMachine.GetSubStateTimer(entity);
                timer.ResetSeconds(0.5f);

                entity.PlaySound(VanillaSoundID.krakenEyes);
            }
            public override void OnExit(EntityStateMachine machine, Entity entity)
            {
                base.OnExit(machine, entity);
                SetBlueEyeTargetRotation(entity, 0);
                SetGreenEyeTargetRotation(entity, 0);
            }
            public override void OnUpdateAI(EntityStateMachine stateMachine, Entity entity)
            {
                base.OnUpdateAI(stateMachine, entity);
                var timer = stateMachine.GetSubStateTimer(entity);
                timer.Run(stateMachine.GetSpeed(entity));
                var substate = stateMachine.GetSubState(entity);
                switch (substate)
                {
                    case SUBSTATE_START:
                        SetEyesState(stateMachine, entity);
                        break;
                    case SUBSTATE_BARRAGE_EYE_START:
                        if (timer.Expired)
                        {
                            stateMachine.StartSubState(entity, SUBSTATE_BARRAGE_EYE);
                            timer.ResetSeconds(BARRAGE_EYE_DURATION);

                            entity.PlaySound(VanillaSoundID.krakenBarrage);
                        }
                        break;
                    case SUBSTATE_BARRAGE_EYE:
                        var interval = Ticks.FromSeconds(BARRAGE_EYE_DURATION) / BARRAGE_EYE_GROUP_COUNT;
                        int count = timer.PassedIntervalCount(interval);
                        for (int i = 0; i < count; i++)
                        {
                            var position = GetBlueEyePosition(entity);
                            var direction = GetBlueEyeDirection(entity);
                            var damage = entity.GetDamage() * BARRAGE_EYE_DAMAGE_MULTIPLIER;
                            var spreadCount = BARRAGE_EYE_SPREAD_COUNT;
                            var angle = BARRAGE_EYE_SPREAD_ANGLE;
                            var speed = BARRAGE_EYE_SHOT_SPEED;
                            FireAGroupOfSpreadProjectiles(entity, position, direction, damage, spreadCount, angle, speed);
                        }
                        if (timer.Expired)
                        {
                            if (TrySetToGreenEye(stateMachine, entity))
                                break;
                            EndState(stateMachine, entity);
                        }
                        break;
                    case SUBSTATE_FLAME_EYE_START:
                        if (timer.Expired)
                        {
                            stateMachine.StartSubState(entity, SUBSTATE_FLAME_EYE);
                            timer.ResetSeconds(2f);

                            entity.PlaySound(VanillaSoundID.krakenCursedFlame);
                        }
                        break;
                    case SUBSTATE_FLAME_EYE:
                        if (timer.PassedInterval(FLAME_EYE_INTERVAL))
                        {
                            var position = GetGreenEyePosition(entity);
                            var direction = GetGreenEyeDirection(entity);
                            var damage = entity.GetDamage() * FLAME_EYE_DAMAGE_MULTIPLIER;
                            var speed = FLAME_EYE_SHOT_SPEED;
                            ShootCursedFlameBreath(entity, position, direction * speed, damage);
                        }
                        if (timer.Expired)
                        {
                            EndState(stateMachine, entity);
                        }
                        break;
                    case SUBSTATE_END:
                        if (timer.Expired)
                        {
                            stateMachine.StartState(entity, STATE_IDLE);
                            CommandTentaclesToAttack(entity);
                        }
                        break;
                }
            }
            public override void OnUpdateLogic(EntityStateMachine machine, Entity entity)
            {
                base.OnUpdateLogic(machine, entity);
                CheckDeath(entity);
            }
            private static void SetEyesState(EntityStateMachine machine, Entity entity)
            {
                if (TrySetToBlueEye(machine, entity))
                    return;
                if (TrySetToGreenEye(machine, entity))
                    return;
                EndState(machine, entity);
            }
            private static bool TrySetToBlueEye(EntityStateMachine machine, Entity entity)
            {
                var blueEyeTarget = FindBarrageEyeTarget(entity);
                if (blueEyeTarget.ExistsAndAlive())
                {
                    var position = GetBlueEyePosition(entity);
                    var targetPosition = blueEyeTarget.GetCenter();
                    var distance = targetPosition - position;
                    var facing = entity.GetFacingDirection();
                    var direction2D = new Vector2(distance.x, distance.z).normalized;
                    var facing2D = new Vector2(facing.x, facing.z).normalized;
                    var rotation = GetEyeRotation(direction2D, facing2D);
                    SetBlueEyeTargetRotation(entity, rotation);

                    machine.StartSubState(entity, SUBSTATE_BARRAGE_EYE_START);
                    var timer = stateMachine.GetSubStateTimer(entity);
                    timer.ResetSeconds(EYE_START_DURATION);
                    return true;
                }
                return false;
            }
            private static bool TrySetToGreenEye(EntityStateMachine machine, Entity entity)
            {
                var greenEyeTarget = FindFlameEyeTarget(entity);
                if (greenEyeTarget.ExistsAndAlive())
                {
                    var position = GetGreenEyePosition(entity);
                    var targetPosition = greenEyeTarget.GetCenter();
                    var distance = targetPosition - position;
                    var facing = entity.GetFacingDirection();
                    var direction2D = new Vector2(distance.x, distance.z).normalized;
                    var facing2D = new Vector2(facing.x, facing.z).normalized;
                    var rotation = GetEyeRotation(direction2D, facing2D);
                    SetGreenEyeTargetRotation(entity, rotation);

                    machine.StartSubState(entity, SUBSTATE_FLAME_EYE_START);
                    var timer = stateMachine.GetSubStateTimer(entity);
                    timer.ResetSeconds(EYE_START_DURATION);
                    return true;
                }
                return false;
            }
            public static float GetEyeRotation(Vector2 direction, Vector2 facing)
            {
                if (direction.sqrMagnitude < 1e-8f)
                    return 0f;

                // facing 应为单位向量，例如 Vector2.left 或 Vector2.right
                float forward = Vector2.Dot(direction, facing); // direction 在 facing 方向上的投影
                return Mathf.Atan2(direction.y, forward) * Mathf.Rad2Deg;
            }
            public static void EndState(EntityStateMachine stateMachine, Entity entity)
            {
                stateMachine.StartSubState(entity, SUBSTATE_END);
                var timer = stateMachine.GetSubStateTimer(entity);
                timer.ResetSeconds(0.5f);
            }
            public const int SUBSTATE_START = 0;
            public const int SUBSTATE_BARRAGE_EYE_START = 1;
            public const int SUBSTATE_BARRAGE_EYE = 2;
            public const int SUBSTATE_FLAME_EYE_START = 3;
            public const int SUBSTATE_FLAME_EYE = 4;
            public const int SUBSTATE_END = 5;
            public const float EYE_START_DURATION = 1f;
            public const float BARRAGE_EYE_DURATION = 0.5f;
            public const int ANIMATION_SUBSTATE_START = 0;
            public const int ANIMATION_SUBSTATE_END = 1;
        }
        #endregion

        #region 激光眼
        public static bool HasLaserEyeTarget(Entity boss)
        {
            return FindLaserEyeLane(boss) >= 0;
        }
        public static int FindLaserEyeLane(Entity boss)
        {
            var laserTimes = GetLaserFiredTimes(boss);
            int mode = LASER_EYE_MODE_RANDOM;
            switch (laserTimes)
            {
                case LASER_TIMES_AIM_NO_STONES:
                    mode = LASER_EYE_MODE_NO_GIANT_STONES;
                    break;
                case LASER_TIMES_AIM_STONES:
                    mode = LASER_EYE_MODE_ONLY_GIANT_STONES;
                    break;
            }
            return FindRandomLaserEyeLane(boss, boss.RNG, mode);
        }
        public static int FindRandomLaserEyeLane(Entity boss, RandomGenerator rng, int mode)
        {
            var rect = boss.GetOverlappedTileRect();
            var minLane = rect.min.y;
            var maxLane = rect.max.y;

            using var lanesItem = ListPool<int>.Rent();
            var candidateLanes = lanesItem.Value;

            for (int i = minLane; i < maxLane; i++)
            {
                if (LaneHasLaserEyeTarget(boss, i))
                {
                    candidateLanes.Add(i);
                }
            }
            if (candidateLanes.Count <= 0)
                return -1;

            switch (mode)
            {
                case LASER_EYE_MODE_NO_GIANT_STONES:
                    return candidateLanes.GetRandomOfTopOnes(lane => GetLaserEyeGiantStonePriorityOfLane(boss, lane), rng, true);
                case LASER_EYE_MODE_ONLY_GIANT_STONES:
                    return candidateLanes.GetRandomOfTopOnes(lane => GetLaserEyeGiantStonePriorityOfLane(boss, lane), rng, false);
                case LASER_EYE_MODE_RANDOM:
                default:
                    return candidateLanes.Random(rng);
            }
        }
        public static bool LaneHasLaserEyeTarget(Entity boss, int lane)
        {
            var level = boss.Level;
            return level.EntityExists(e => e.GetLane() == lane && IsLaserEyeTarget(boss, e));
        }
        public static bool IsLaserEyeTarget(Entity boss, Entity target)
        {
            if (!target.ExistsAndAlive())
                return false;
            if (!boss.IsHostile(target))
                return false;
            if (!Detection.CanDetect(target))
                return false;
            var facingX = boss.GetFacingX();
            var bossX = GetLaserEyePosition(boss).x;
            var targetX = target.Position.x;
            if ((targetX - bossX) * facingX < 0)
                return false;
            return true;
        }
        public static float GetLaserEyeGiantStonePriorityOfLane(Entity boss, int lane)
        {
            using var stonesItem = ListPool<Entity>.Rent();
            var stones = stonesItem.Value;

            boss.Level.FindEntitiesNonAlloc(e => e.GetLane() == lane && IsLaserEyeTarget(boss, e) && e.IsEntityOf(VanillaContraptionID.giantStone), stones);

            float score = 0;
            var bossX = GetLaserEyePosition(boss).x;
            foreach (var stone in stones)
            {
                var distance = Mathf.Abs(stone.Position.x - bossX);
                score += distance;
                score += stone.Health;
            }
            return score;
        }
        private class LaserEyeState : EntityStateMachineState
        {
            public LaserEyeState() : base(STATE_LASER_EYE, ANIMATION_STATE_LASER_EYE) { }
            public override int GetAnimationSubstate(int substate)
            {
                switch (substate)
                {
                    case SUBSTATE_END:
                        return ANIMATION_SUBSTATE_END;
                    case SUBSTATE_START:
                        return ANIMATION_SUBSTATE_START;
                }
                return ANIMATION_SUBSTATE_LOOP;
            }
            public override void OnEnter(EntityStateMachine stateMachine, Entity entity)
            {
                base.OnEnter(stateMachine, entity);
                SetExposedStates(entity, true);

                var timer = stateMachine.GetSubStateTimer(entity);
                timer.ResetSeconds(START_SECONDS);

                entity.PlaySound(VanillaSoundID.krakenLaserReadyRoar);

                SpawnLaserTileWarningTargets(entity);
            }
            public override void OnExit(EntityStateMachine machine, Entity entity)
            {
                base.OnExit(machine, entity);
                SetLaserCharging(entity, false);
                RemoveDeathRay(entity);
                RemoveWarningTargets(entity);
            }
            public override void OnUpdateAI(EntityStateMachine stateMachine, Entity entity)
            {
                base.OnUpdateAI(stateMachine, entity);
                var timer = stateMachine.GetSubStateTimer(entity);
                timer.Run(stateMachine.GetSpeed(entity));
                var substate = stateMachine.GetSubState(entity);
                switch (substate)
                {
                    case SUBSTATE_START:
                        if (timer.Expired)
                        {
                            stateMachine.StartSubState(entity, SUBSTATE_START_2);
                            timer.ResetSeconds(START_SECONDS_2);
                        }
                        break;
                    case SUBSTATE_START_2:
                        if (timer.Expired)
                        {
                            stateMachine.StartSubState(entity, SUBSTATE_LASER_CHARGING);
                            timer.ResetSeconds(LASER_CHARGE_SECONDS);

                            entity.PlaySound(VanillaSoundID.krakenLaserReadyRoar);
                            entity.PlaySound(VanillaSoundID.krakenLaserCharge);
                            SetLaserCharging(entity, true);
                        }
                        break;
                    case SUBSTATE_LASER_CHARGING:
                        if (timer.Expired)
                        {
                            stateMachine.StartSubState(entity, SUBSTATE_LASER_FIRE);
                            timer.ResetSeconds(LASER_FIRE_DURATION_SECONDS);

                            var lane = GetTargetLane(entity);
                            var totalDamage = entity.GetDamage() * DEATH_RAY_TOTAL_DAMAGE_MULTIPLIER;
                            FireDeathRay(entity, lane, totalDamage);
                            SetLaserCharging(entity, false);
                            RemoveWarningTargets(entity);
                            SetLaserFiredTimes(entity, GetLaserFiredTimes(entity) + 1);

                            entity.PlaySound(VanillaSoundID.krakenDeathRay);
                        }
                        break;
                    case SUBSTATE_LASER_FIRE:
                        var deathRayID = GetDeathRay(entity);
                        var deathRay = deathRayID?.GetEntity(entity.Level);
                        if (deathRay.ExistsAndAlive())
                        {
                            deathRay.Position = GetLaserEyePosition(entity);
                        }
                        if (timer.Expired)
                        {
                            stateMachine.StartSubState(entity, SUBSTATE_END);
                            timer.ResetSeconds(LASER_END_DURATION_SECONDS);
                            if (deathRay.ExistsAndAlive())
                            {
                                KrakenDeathRay.Shrink(deathRay);
                                SetDeathRay(entity, null);
                            }
                        }
                        break;
                    case SUBSTATE_END:
                        if (timer.Expired)
                        {
                            stateMachine.StartState(entity, STATE_IDLE);
                            CommandTentaclesToAttack(entity);
                        }
                        break;
                }
            }
            public override void OnUpdateLogic(EntityStateMachine machine, Entity entity)
            {
                base.OnUpdateLogic(machine, entity);
                CheckDeath(entity);
            }
            public void SpawnLaserTileWarningTargets(Entity entity)
            {
                int lane = GetTargetLane(entity);
                if (lane < 0)
                    return;
                var targets = GetWarningTargets(entity);
                if (targets == null)
                {
                    targets = new List<EntityID>();
                    SetWarningTargets(entity, targets);
                }
                var level = entity.Level;
                var takenRect = entity.GetOverlappedTileRect();
                int minColumn;
                int maxColumn;
                if (entity.IsFacingLeft())
                {
                    minColumn = 0;
                    maxColumn = takenRect.min.x - 1;
                }
                else
                {
                    minColumn = takenRect.max.x + 1;
                    maxColumn = level.GetMaxColumnCount() - 1;
                }
                var spawnParams = entity.GetSpawnParams();
                spawnParams.EntityParent = entity;
                for (int column = minColumn; column <= maxColumn; column++)
                {
                    var position = level.GetEntityGridPosition(column, lane);
                    var target = entity.Spawn(VanillaEffectID.aimTarget, position, spawnParams);
                    if (target != null)
                    {
                        targets.Add(new EntityID(target));
                    }
                }
            }
            public const int SUBSTATE_START = 0;
            public const int SUBSTATE_START_2 = 1;
            public const int SUBSTATE_LASER_CHARGING = 2;
            public const int SUBSTATE_LASER_FIRE = 3;
            public const int SUBSTATE_END = 4;
            public const float START_SECONDS = 0.5f;
            public const float START_SECONDS_2 = 2.5f;
            public const float LASER_CHARGE_SECONDS = 3f;
            public const float LASER_FIRE_DURATION_SECONDS = 3f;
            public const float LASER_END_DURATION_SECONDS = 0.5f;
            public const int ANIMATION_SUBSTATE_START = 0;
            public const int ANIMATION_SUBSTATE_LOOP = 1;
            public const int ANIMATION_SUBSTATE_END = 2;
        }
