        #region 吸水
        public static RectInt GetAbsorbTileRange(Entity entity)
        {
            var rect = entity.GetOverlappedTileRect();
            var minLane = rect.min.y;
            var maxLane = rect.max.y;
            int minColumn, maxColumn;
            var level = entity.Level;
            if (entity.IsFacingLeft())
            {
                maxColumn = rect.min.x - 1;
                minColumn = maxColumn + 1 - ABSORB_COLUMN_RANGE;
            }
            else
            {
                minColumn = rect.max.x + 1;
                maxColumn = minColumn - 1 + ABSORB_COLUMN_RANGE;
            }
            return new RectInt(minColumn, minLane, maxColumn - minColumn, maxLane - minLane);
        }
        public static bool CanBeAbsorbTarget(Entity entity, Entity target)
        {
            if (!target.ExistsAndAlive())
                return false;
            if (!entity.IsHostile(target))
                return false;
            if (!target.IsOnGround)
                return false;
            if (target.IsSuspendingContraption())
                return false;
            if (target.IsStableContraption())
                return false;
            return true;
        }
        public static bool HasAbsorbTarget(Entity entity)
        {
            var level = entity.Level;
            var rect = GetAbsorbTileRange(entity);
            for (int c = rect.min.x; c <= rect.max.x; c++)
            {
                for (int l = rect.min.y; l <= rect.max.y; l++)
                {
                    var grid = level.GetGrid(c, l);
                    if (grid != null && grid.HasEntity(e => CanBeAbsorbTarget(entity, e)))
                    {
                        return true;
                    }
                }
            }
            return false;
        }
        public static void GetAbsorbTiles(Entity entity, List<LawnGrid> results)
        {
            var level = entity.Level;
            var rect = GetAbsorbTileRange(entity);
            for (int c = rect.min.x; c <= rect.max.x; c++)
            {
                for (int l = rect.min.y; l <= rect.max.y; l++)
                {
                    var grid = level.GetGrid(c, l);
                    if (grid != null)
                        results.Add(grid);
                }
            }
        }
        private class AbsorbState : EntityStateMachineState
        {
            public AbsorbState() : base(STATE_ABSORB, ANIMATION_STATE_ABSORB) { }
            public override int GetAnimationSubstate(int substate)
            {
                switch (substate)
                {
                    case SUBSTATE_END:
                        return ANIMATION_SUBSTATE_END;
                    case SUBSTATE_START:
                        return ANIMATION_SUBSTATE_START;
                }
                return ANIMATION_SUBSTATE_LOOP;
            }
            public override void OnEnter(EntityStateMachine stateMachine, Entity entity)
            {
                base.OnEnter(stateMachine, entity);
                SetExposedStates(entity, true);

                var timer = stateMachine.GetSubStateTimer(entity);
                timer.ResetSeconds(START_SECONDS);

                entity.PlaySound(VanillaSoundID.krakenAbsorbRoar);

                SpawnTileWarningTargets(entity);
            }
            public override void OnExit(EntityStateMachine machine, Entity entity)
            {
                base.OnExit(machine, entity);
                RemoveWarningTargets(entity);
                entity.RemoveBuffs<KrakenAbsorbedDynamiteBuff>();
            }
            public override void OnUpdateAI(EntityStateMachine stateMachine, Entity entity)
            {
                base.OnUpdateAI(stateMachine, entity);
                var timer = stateMachine.GetSubStateTimer(entity);
                timer.Run(stateMachine.GetSpeed(entity));
                var substate = stateMachine.GetSubState(entity);
                switch (substate)
                {
                    case SUBSTATE_START:
                        if (timer.Expired)
                        {
                            stateMachine.StartSubState(entity, SUBSTATE_START_2);
                            timer.ResetSeconds(START_SECONDS_2);
                        }
                        break;
                    case SUBSTATE_START_2:
                        if (timer.Expired)
                        {
                            stateMachine.StartSubState(entity, SUBSTATE_ABSORB);
                            timer.ResetSeconds(ABSORB_SECONDS);

                            entity.PlaySound(VanillaSoundID.krakenAbsorb);
                            Absorb(entity);
                            RemoveWarningTargets(entity);
                        }
                        break;
                    case SUBSTATE_ABSORB:
                        if (timer.Expired)
                        {
                            using var buffsItem = ListPool<Buff>.Rent();
                            var buffs = buffsItem.Value;

                            entity.GetBuffs<KrakenAbsorbedDynamiteBuff>(buffs);
                            if (buffs.Count > 0)
                            {
                                Stun(entity, STUN_SECONDS);
                                PlayCriticalEffects(entity, entity.Position);
                                Explosion.Spawn(entity, entity.Position, 120);
                                entity.Level.ShakeScreen(10, 0, 15);
                                entity.PlaySound(VanillaSoundID.largeExplosion);
                                entity.TakeDamage(INNER_EXPLOSION_DAMAGE, new DamageEffectList(VanillaDamageEffects.EXPLOSION), entity);
                                entity.RemoveBuffs<KrakenAbsorbedDynamiteBuff>();
                            }
                            else
                            {
                                stateMachine.StartSubState(entity, SUBSTATE_END);
                                timer.ResetSeconds(END_DURATION_SECONDS);
                            }
                        }
                        break;
                    case SUBSTATE_END:
                        if (timer.Expired)
                        {
                            stateMachine.StartState(entity, STATE_IDLE);
                            CommandTentaclesToAttack(entity);
                        }
                        break;
                }
            }
            public override void OnUpdateLogic(EntityStateMachine machine, Entity entity)
            {
                base.OnUpdateLogic(machine, entity);
                CheckDeath(entity);
            }
            public void Absorb(Entity entity)
            {
                using var absorbTilesItem = ListPool<LawnGrid>.Rent();
                var absorbTiles = absorbTilesItem.Value;

                using var tileEntsItem = ListPool<Entity>.Rent();
                var tileEnts = tileEntsItem.Value;

                GetAbsorbTiles(entity, absorbTiles);

                var targetPosition = GetAbsorbTargetPosition(entity);
                foreach (var tile in absorbTiles)
                {
                    tileEnts.Clear();
                    tile.GetEntities(tileEnts);
                    foreach (var ent in tileEnts)
                    {
                        if (!CanBeAbsorbTarget(entity, ent))
                            continue;
                        var buff = ent.NewBuff<AbsorbedByKrakenBuff>();
                        AbsorbedByKrakenBuff.SetKrakenID(buff, new EntityID(entity));
                        ent.AddBuff(buff);
                    }
                }
            }
            public void SpawnTileWarningTargets(Entity entity)
            {
                int lane = GetTargetLane(entity);
                if (lane < 0)
                    return;
                var targets = GetWarningTargets(entity);
                if (targets == null)
                {
                    targets = new List<EntityID>();
                    SetWarningTargets(entity, targets);
                }
                var level = entity.Level;

                using var absorbTilesItem = ListPool<LawnGrid>.Rent();
                var absorbTiles = absorbTilesItem.Value;

                GetAbsorbTiles(entity, absorbTiles);
                var spawnParams = entity.GetSpawnParams();
                spawnParams.EntityParent = entity;
                foreach (var tile in absorbTiles)
                {
                    var position = tile.GetEntityPosition();
                    var target = entity.Spawn(VanillaEffectID.aimTarget, position, spawnParams);
                    if (target != null)
                    {
                        targets.Add(new EntityID(target));
                    }
                }
            }
            public const int SUBSTATE_START = 0;
            public const int SUBSTATE_START_2 = 1;
            public const int SUBSTATE_ABSORB = 2;
            public const int SUBSTATE_END = 3;
            public const float START_SECONDS = 0.5f;
            public const float START_SECONDS_2 = 2.5f;
            public const float ABSORB_SECONDS = 3f;
            public const float END_DURATION_SECONDS = 0.5f;
            public const int ANIMATION_SUBSTATE_START = 0;
            public const int ANIMATION_SUBSTATE_LOOP = 1;
            public const int ANIMATION_SUBSTATE_END = 2;
        }
        #endregion

