        public static RectInt GetDrainageTileRange(Entity entity)
        {
            var rect = entity.GetOverlappedTileRect();
            var minLane = rect.min.y;
            var maxLane = rect.max.y;
            int minColumn, maxColumn;
            var level = entity.Level;
            if (entity.IsFacingLeft())
            {
                maxColumn = rect.min.x + 1;
                minColumn = maxColumn + 1 - DRAINAGE_COLUMN_RANGE;
            }
            else
            {
                minColumn = rect.max.x - 1;
                maxColumn = minColumn - 1 + DRAINAGE_COLUMN_RANGE;
            }
            return new RectInt(minColumn, minLane, maxColumn - minColumn, maxLane - minLane);
        }
        public static bool HasDrainageTarget(Entity entity)
        {
            return true;
        }
        public static void GetDrainageTiles(Entity entity, List<LawnGrid> results)
        {
            var level = entity.Level;
            var rect = GetDrainageTileRange(entity);
            for (int c = rect.min.x; c <= rect.max.x; c++)
            {
                for (int l = rect.min.y; l <= rect.max.y; l++)
                {
                    var grid = level.GetGrid(c, l);
                    if (grid != null)
                        results.Add(grid);
                }
            }
