        public static void SpawnDrainageSplashes(Entity entity, int timeout)
        {
            using var tilesItem = ListPool<LawnGrid>.Rent();
            var tiles = tilesItem.Value;

            GetDrainageTiles(entity, tiles);

            var splashes = GetDrainageSplashes(entity);
            if (splashes == null)
            {
                splashes = new List<EntityID>();
                SetDrainageSplashes(entity, splashes);
            }
            var args = entity.GetSpawnParams();
            args.SetProperty(VanillaEntityProps.MAX_TIMEOUT, timeout);
            args.SetProperty(VanillaEntityProps.DAMAGE, entity.GetDamage() * DRAINAGE_SPLASH_DAMAGE_MULTIPLIER);
            foreach (var tile in tiles)
            {
                var splash = entity.Spawn(VanillaEffectID.krakenDrainageSplash, tile.GetEntityPosition(), args);
                if (splash != null)
                {
                    splashes.Add(new EntityID(splash));
                }
            }
        }
        public static void StopAllDrainageSplashes(Entity entity)
        {
            var splashes = GetDrainageSplashes(entity);
            if (splashes == null)
            {
                return;
            }
            foreach (var splashID in splashes)
            {
                var splash = splashID?.GetEntity(entity.Level);
                if (splash.ExistsAndAlive())
                {
                    KrakenDrainageSplash.Stop(splash);
                }
            }
            splashes.Clear();
        }
        private class DrainageState : EntityStateMachineState
        {
            public DrainageState() : base(STATE_DRAINAGE, ANIMATION_STATE_IDLE) { }
            public override void OnEnter(EntityStateMachine stateMachine, Entity entity)
            {
                base.OnEnter(stateMachine, entity);
                SetExposedStates(entity, true);

                var timer = stateMachine.GetStateTimer(entity);
                timer.ResetSeconds(DURATION_SECONDS);

                entity.PlaySound(VanillaSoundID.fizz, 0.5f, 2);
                entity.PlaySound(VanillaSoundID.krakenDrainage);

                SpawnDrainageSplashes(entity, Ticks.FromSeconds(DURATION_SECONDS));
            }
            public override void OnExit(EntityStateMachine machine, Entity entity)
            {
                base.OnExit(machine, entity);
                StopAllDrainageSplashes(entity);
            }
            public override void OnUpdateAI(EntityStateMachine stateMachine, Entity entity)
            {
                base.OnUpdateAI(stateMachine, entity);
                var timer = stateMachine.GetStateTimer(entity);
                timer.Run(stateMachine.GetSpeed(entity));
                if (timer.Expired)
                {
                    stateMachine.StartState(entity, STATE_IDLE);
                    CommandTentaclesToAttack(entity);
                }
            }
            public override void OnUpdateLogic(EntityStateMachine machine, Entity entity)
            {
                base.OnUpdateLogic(machine, entity);
                CheckDeath(entity);
            }
            public const float DURATION_SECONDS = 6f;
        }
